//! Fixed FFmpeg render graph compilation.
//!
//! Compiles a deterministic FFmpeg filter graph from a validated plan.
//! Labels are generated by shot index only. All text is already rasterized
//! into PNG overlays. No user/model strings enter the graph.

use std::ffi::{OsStr, OsString};
use std::path::Path;

use super::error::LaunchTeaserRenderError;
use super::overlay::OverlayAsset;
use super::plan::{
    ValidatedLaunchTeaserPlan, FINAL_FPS, FINAL_HEIGHT, FINAL_WIDTH, PREVIEW_HEIGHT, PREVIEW_WIDTH,
};

/// Render output profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RenderProfile {
    /// Full-resolution final output (1920x1080).
    Final,
    /// Half-resolution preview (960x540).
    Preview,
}

impl RenderProfile {
    /// Output width for this profile.
    pub fn width(&self) -> u32 {
        match self {
            Self::Final => FINAL_WIDTH,
            Self::Preview => PREVIEW_WIDTH,
        }
    }

    /// Output height for this profile.
    pub fn height(&self) -> u32 {
        match self {
            Self::Final => FINAL_HEIGHT,
            Self::Preview => PREVIEW_HEIGHT,
        }
    }
}

/// A compiled FFmpeg graph ready for process spawn.
#[derive(Debug, Clone)]
pub struct CompiledLaunchTeaserGraph {
    args: Vec<OsString>,
}

impl CompiledLaunchTeaserGraph {
    /// The full argument list for FFmpeg invocation.
    pub fn args(&self) -> &[OsString] {
        &self.args
    }
}

/// Compile the fixed FFmpeg render graph.
///
/// The filter graph is written to a scratch file and passed as an argument.
/// No user/model text enters the graph because all text is already rasterized.
pub fn compile_ffmpeg_graph(
    plan: &ValidatedLaunchTeaserPlan,
    motion_path: &Path,
    overlays: &[OverlayAsset],
    output_path: &Path,
    profile: RenderProfile,
    scratch: &Path,
) -> Result<CompiledLaunchTeaserGraph, LaunchTeaserRenderError> {
    let plan_inner = plan.plan();
    let shot_count = plan_inner.shots.len();
    let out_w = profile.width();
    let out_h = profile.height();

    // Build the filter graph.
    let mut filters = Vec::new();

    // For each shot: trim, setpts, crop (focus interpolation), scale+pad.
    for (i, shot) in plan_inner.shots.iter().enumerate() {
        let start_pts = shot.source_start_ms as f64 / 1_000.0;
        let end_pts = shot.source_end_ms as f64 / 1_000.0;

        // Trim and reset PTS.
        filters.push(format!(
            "[0:v]trim=start={start_pts}:end={end_pts},setpts=PTS-STARTPTS[trim{i}]"
        ));

        // Focus crop: interpolate center from start to end.
        // Source dimensions are used for crop geometry.
        let src_w = plan_inner.source.motion_width;
        let src_h = plan_inner.source.motion_height;

        // Compute crop size based on zoom.
        let zoom = shot.focus_path.zoom_permille as f64 / 1_000.0;
        let crop_w = ((src_w as f64) / zoom) as u32;
        let crop_h = ((src_h as f64) / zoom) as u32;

        // Compute crop position from normalized focus points (0-10000).
        // Center: start and end are the same for default plans.
        let cx_start = (shot.focus_path.start.x as f64 / 10_000.0) * src_w as f64;
        let cy_start = (shot.focus_path.start.y as f64 / 10_000.0) * src_h as f64;
        let cx_end = (shot.focus_path.end.x as f64 / 10_000.0) * src_w as f64;
        let cy_end = (shot.focus_path.end.y as f64 / 10_000.0) * src_h as f64;

        let displayed_dur_ms = shot.displayed_ms();
        let displayed_dur_s = displayed_dur_ms as f64 / 1_000.0;

        // Interpolated crop position.
        let crop_x_expr = format!("'({cx_start})+(({cx_end})-({cx_start}))*t/{displayed_dur_s}'");
        let crop_y_expr = format!("'({cy_start})+(({cy_end})-({cy_start}))*t/{displayed_dur_s}'");

        // Clamp crop to stay within source bounds.
        let crop_x_expr = format!("'min(max({crop_x_expr}-({crop_w}/2),0),{src_w}-{crop_w})'");
        let crop_y_expr = format!("'min(max({crop_y_expr}-({crop_h}/2),0),{src_h}-{crop_h})'");

        filters.push(format!(
            "[trim{i}]crop={crop_w}:{crop_h}:{crop_x_expr}:{crop_y_expr}[crop{i}]"
        ));

        // Scale and pad to output dimensions.
        filters.push(format!(
            "[crop{i}]scale={out_w}:{out_h}:force_original_aspect_ratio=decrease,pad={out_w}:{out_h}:(ow-iw)/2:(oh-ih)/2[scaled{i}]"
        ));

        // Apply ALL overlays for this shot, chained sequentially.
        // Shot 0 may have hook + caption; final shot may have caption + outro.
        let shot_overlays: Vec<&OverlayAsset> =
            overlays.iter().filter(|o| o.shot_index == i).collect();
        for (k, overlay) in shot_overlays.iter().enumerate() {
            let overlay_path = overlay.path.to_string_lossy();
            let input = if k == 0 {
                format!("[scaled{i}]")
            } else {
                let prev = k - 1;
                format!("[ovr{i}_{prev}]")
            };
            let output = if k == shot_overlays.len() - 1 {
                format!("[shot{i}]")
            } else {
                format!("[ovr{i}_{k}]")
            };
            filters.push(format!(
                "movie={overlay_path}[ovr{i}_{k}];{input}[ovr{i}_{k}]overlay=0:0{output}"
            ));
        }
    }

    // Concatenate shots. Determine the final label per shot.
    let mut concat_inputs = String::new();
    let mut shot_labels = Vec::new();
    for i in 0..shot_count {
        let has_overlay = overlays.iter().any(|o| o.shot_index == i);
        let label = if has_overlay {
            format!("[shot{i}]")
        } else {
            format!("[scaled{i}]")
        };
        concat_inputs.push_str(&label);
        shot_labels.push(label);
    }

    // Check for crossfades between adjacent shots.
    let has_any_crossfade = plan_inner
        .shots
        .iter()
        .any(|s| matches!(s.transition, super::plan::TransitionV1::Crossfade { .. }));

    if has_any_crossfade {
        // Use xfade chain for crossfade transitions.
        let mut current = shot_labels[0].clone();
        for (i, shot) in plan_inner.shots.iter().enumerate().skip(1) {
            if let super::plan::TransitionV1::Crossfade { duration_ms } = shot.transition {
                let offset_s = plan_inner.cumulative_start_ms(i) as f64 / 1_000.0
                    - (duration_ms as f64 / 1_000.0);
                let next = if i == shot_count - 1 {
                    "[outv]".to_string()
                } else {
                    format!("[xfade{i}]")
                };
                filters.push(format!(
                    "{current}{next_input}xfade=transition=fade:duration={dur}:offset={offset}{next}",
                    next_input = shot_labels[i],
                    dur = duration_ms as f64 / 1_000.0,
                    offset = offset_s.max(0.0),
                ));
                current = next;
            } else {
                // Cut: concat current + this shot, then continue.
                let next = if i == shot_count - 1 {
                    "[outv]".to_string()
                } else {
                    format!("[xfade{i}]")
                };
                filters.push(format!(
                    "{current}{label}concat=n=2:v=1:a=0{next}",
                    label = shot_labels[i],
                ));
                current = next;
            }
        }
    } else {
        // Simple concat for all-cut transitions.
        filters.push(format!(
            "{concat_inputs}concat=n={shot_count}:v=1:a=0[outv]"
        ));
    }

    let filter_graph = filters.join(";\n");

    // Write filter graph to a scratch file.
    let filter_path = scratch.join("filter.txt");
    std::fs::write(&filter_path, &filter_graph)
        .map_err(|_| LaunchTeaserRenderError::GraphCompilationFailed)?;

    // Build FFmpeg arguments.
    let mut args: Vec<OsString> = vec![
        OsStr::new("-y").into(),
        OsStr::new("-nostdin").into(),
        OsStr::new("-i").into(),
        motion_path.into(),
        OsStr::new("-filter_complex_script").into(),
        filter_path.into(),
    ];

    // Map the final output label.
    args.push(OsStr::new("-map").into());
    args.push(OsStr::new("[outv]").into());

    // Video codec settings.
    args.push(OsStr::new("-c:v").into());
    args.push(OsStr::new("libx264").into());
    args.push(OsStr::new("-pix_fmt").into());
    args.push(OsStr::new("yuv420p").into());
    args.push(OsStr::new("-r").into());
    args.push(OsStr::new(&FINAL_FPS.to_string()).into());

    // No audio.
    args.push(OsStr::new("-an").into());

    // Output path.
    args.push(output_path.into());

    Ok(CompiledLaunchTeaserGraph { args })
}

