        let plan = valid_plan().validate().unwrap();
        let scratch = tempfile::tempdir().unwrap();
        let assets = prepare_overlay_assets(&plan, scratch.path(), RenderProfile::Final).unwrap();
        let motion = Path::new("/tmp/fake.mp4");
